# Hybrid hypothesis: 
# 1. Start with dest row's original values
# 2. Overlay copied pattern where source has non-bg values
# Only source cells that AREN'T bg will be written; rest stay as-is

def compute_v13(grid):
    """Overlay-based transformation: keep dest values unless source says otherwise"""
    result = [[bg_val]*w for _ in range(h)]

    # Handle separators
    for r in range(h):
        for c in range(w):
            if r in h_rows or c in v_cols:
                result[r][c] = sep_val

    for r in range(h):
        for c in range(w):
            if r in h_rows or c in v_cols:
                continue

            src_r = r % (min_hrow + 1)

            if c < sorted_v[0]:
                local_c = c
            elif c > sorted_v[-1]:
                local_c = c - sorted_v[-1] - 1
            else:
                local_c = c % (sorted_v[-1] - sorted_v[0] + 1)

            # Source row: copy directly
            if r < min_hrow:
                result[r][c] = grid[r][c]
            else:
                # Dest row: start with own value, then potentially update
                val_from_src = grid[src_r][local_c]
                current_val = grid[r][c]

                # If source has NON-bg at this position, use it
                # Otherwise, keep dest's original value
                if val_from_src != bg_val:
                    result[r][c] = val_from_src
                else:
                    result[r][c] = current_val  # Keep original

    return result

