def compute_v14(grid):
    """Mirror non-bg values from each vseg to others at same local positions"""
    result = [[bg_val]*w for _ in range(h)]

    sorted_v = sorted(v_cols)
    segment_widths = []
    for i in range(len(sorted_v)):
        if i == 0:
            seg_start = 0
            seg_end = sorted_v[i] - 1
        else:
            seg_start = sorted_v[i-1] + 1
            seg_end = sorted_v[i] - 1

        width = seg_end - seg_start + 1
        segment_widths.append((seg_start, seg_end, width))

    print(f"Segments: {segment_widths}")

    # Fill separators first
    for r in range(h):
        for c in range(w):
            if r in h_rows or c in v_cols:
                result[r][c] = sep_val

    # For each cell, find ALL cells at same "local position" across vsegs
    # If ANY of them have non-bg value, use it; otherwise bg
    for r in range(h):
        if r in h_rows:
            continue
        for c in range(w):
            if c in v_cols:
                continue

            src_r = r % (min(h_rows) + 1) if h_rows else r

            # Get local column within THIS segment
            seg_idx = None
            for i, (s, e, _) in enumerate(segment_widths):
                if s <= c <= e:
                    seg_idx = i
                    break

            if seg_idx is not None:
                local_c = c - segment_widths[seg_idx][0]

                # Now check all other segments at this local position
                non_bg_found = None
                for i, (s, e, _) in enumerate(segment_widths):
                    other_c = s + local_c
                    if other_c >= w:
                        continue

                    if r in h_rows or other_c in v_cols:
                        continue

                    val = grid[src_r][other_c] if src_r < min(h_rows) else grid[src_r % (min(h_rows)+1)][other_c]

                    if val != bg_val:
                        if non_bg_found is None:
                            non_bg_found = val
                        elif non_bg_found != val:
                            # Conflict - keep last? or something else?
                            pass

                if non_bg_found is not None:
                    result[r][c] = non_bg_found

    return result

