    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 8, 8, 3, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],   # dest 1 orig
]

bg_val = 9
sorted_v = [8, 17]
seg_width = 8

def compute_dest_propagate_horizontal(grid):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    for r in range(len(result)):
        for seg_start in [sorted_v[0]+1, sorted_v[1]+1]:
            vals_in_seg = []
            for lc in range(seg_width):
                real_c = seg_start + lc
                if 0 <= real_c < len(result[r]):
                    vals_in_seg.append((real_c, result[r][real_c]))

            # Find last non-bg value in segment
            last_val = None
            for c, val in vals_in_seg:
                if val != bg_val and last_val is None:
                    last_val = val

            # Fill bg cells with last_val
            for c, val in vals_in_seg:
                if val == bg_val:
                    result[r][c] = last_val

    return result

