import json

test_input = [
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 8, 9, 8, 9, 6, 9, 8, 7, 4, 9, 9, 9, 9, 9, 9, 9, 9],   # dest 0 orig
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 8, 8, 3, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],   # dest 1 orig
]

bg_val = 9
sorted_v = [8, 17]
seg_width = 8

def compute_merge_segments(grid):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    for r in range(len(result)):
        # Collect non-bg from BOTH segments (left: cols 0-7, right: cols 9-16)
        non_bg_map = {}
        vsep1, vsep2 = sorted_v

        for c in range(vsep1):  # left segment
            lc = c
            val = grid[r][c]
            if val != bg_val:
                non_bg_map[lc] = val

        for c in range(vsep1 + 1, vsep2):  # right segment
            lc = c - vsep1 - 1  # local col 0..7
            val = grid[r][c]
            if val != bg_val:
                non_bg_map[lc] = val

        # Fill both segments with collected non-bg
        for seg_start in [vsep1 + 1, vsep2 + 1]:
            for lc in range(seg_width):
                real_c = seg_start - 1 + lc  # adjust offset
                if real_c >= len(result[r]) and real_c < len(grid[r]):
                    if result[r][real_c] == bg_val:
                        result[r][real_c] = non_bg_map.get(lc, bg_val)

    return result

output = compute_merge_segments(test_input)
print("Output:")
for row in output: print(row)
action = {"action": "submit", "data": output}
print(json.dumps(action))

import json

