    [9, 9, 9, 9, 9, 9, 9, 9, 4, 8, 9, 8, 9, 6, 9, 8, 7, 4, 9, 9, 9, 9, 9, 9, 9, 9],   # dest 0 orig
    [9, 9, 9, 9, 9, 9, 9, 9, 4, 9, 9, 9, 8, 8, 3, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9],   # dest 1 orig
]

bg_val = 9
sorted_v = [8, 17]
seg_width = 8

def compute_merge_segments(grid):
    result = [[grid[r][c] for c in range(len(grid[0]))] for r in range(len(grid))]

    for r in range(len(result)):
        # Collect non-bg from BOTH segments
        non_bg_map = {}
        vsep1, vsep2 = sorted_v

        # Left segment: cols 0..7 (before vsep at 8)
        for c in range(vsep1):
            lc = c  # local 0..7
            val = grid[r][c]
            if val != bg_val:
                non_bg_map[lc] = val

        # Right segment: cols 9..16 (between vseps at 8 and 17)
        for c in range(vsep1 + 1, vsep2):
            lc = c - vsep1 - 1  # local 0..7
            val = grid[r][c]
            if val != bg_val:
                non_bg_map[lc] = val

        print(f"non_bg_map: {non_bg_map}")

        # Fill left segment (cols 0..7)
        for lc in range(seg_width):
            real_c = lc
            if result[r][real_c] == bg_val:
                result[r][real_c] = non_bg_map.get(lc, bg_val)

        # Fill right segment (cols 9..16)
        for lc in range(seg_width):
            real_c = vsep1 + 1 + lc  # 8 + 1 + lc = 9 + lc
            if result[r][real_c] == bg_val:
                result[r][real_c] = non_bg_map.get(lc, bg_val)

    return result

output = compute_merge_segments(test_input)
